const b = $json.body || $json;
const email = String(b.email || '').trim().toLowerCase();
const name = String(b.name || b.fullName || '').trim();
const company = String(b.company || '').trim();
const message = String(b.message || b.comments || '').slice(0, 4000);
const source = String(b.source || 'website-form').slice(0, 80);
const ok = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)
  && name.length >= 2 && name.length <= 120
  && company.length >= 1 && company.length <= 160;
const today = new Date().toISOString().slice(0,10);
const idemKey = 'lead:' + email + ':' + today;
if (!ok) return { json: { Timestamp: new Date().toISOString(), EventKey: idemKey,
  Workflow: 'lead-routing', Status: 'rejected_invalid_input',
  RawEmail: email || 'missing', Reason: !email ? 'missing_email' : (name.length<2?'bad_name':'bad_company') } };
return { json: { email, name, company, message, source, EventKey: idemKey,
  input_valid: true, receivedAt: new Date().toISOString() } };

// ── Deduplication / Idempotency ──
// PRODUCTION: query Sheets "Leads" tab for existing EventKey (email+date).
// If found → mark duplicate. Demo: always new.
const d = $json;
const isDuplicate = false; // PRODUCTION: Sheets lookup on EventKey
return { json: { ...d, is_duplicate: isDuplicate } };

// ── Company Enrichment ──
// PRODUCTION: Clearbit/Apollo/Hunter API node. Wrap in try/catch — enrichment
// failure must NOT block the lead. Set enriched:false on failure.
const d = $json;
const firmo = {
  "gmail.com": { industry: "Individual / SMB", employees: "1-10", revenue: "<$1M", region: "Unknown" },
};
// Simulated enrichment keyed by email domain
const domain = d.email.split('@')[1] || '';
const demoDB = {
  "acmecorp.com":     { industry: "SaaS / B2B Software", employees: "51-200", revenue: "$5M-$20M", region: "North America", tech: ["Salesforce","HubSpot","AWS"] },
  "globex.io":        { industry: "Fintech", employees: "201-500", revenue: "$20M-$50M", region: "Europe", tech: ["Snowflake","Segment"] },
  "initech.com":      { industry: "Manufacturing", employees: "11-50", revenue: "$1M-$5M", region: "North America", tech: ["QuickBooks"] },
  "brightwavecoffee.com": { industry: "E-commerce (DTC)", employees: "11-50", revenue: "$1M-$5M", region: "North America", tech: ["Shopify","Klaviyo"] }
};
let enriched = demoDB[domain] || firmo[domain] || null;
if (!enriched) {
  // Unknown domain — generic SMB profile, flag as not enriched
  return { json: { ...d, enriched: false, firmographics: { industry: "Unknown", employees: "Unknown", revenue: "Unknown", region: "Unknown" } } };
}
return { json: { ...d, enriched: true, firmographics: enriched } };

