const raw = $json.content?.parts?.filter(p => !p.thought).map(p => p.text || '').join('') ?? $json.text ?? '';
let draft = '';
const s = raw.lastIndexOf('<<<REPLY>>>');
if (s !== -1) { draft = raw.slice(s+11); const e = draft.indexOf('<<<END>>>'); if (e!==-1) draft = draft.slice(0,e); draft = draft.trim(); }
if (draft.length < 30) draft = raw.trim();
const lead = $('Parse Score').item.json;
return { json: { ...lead, replyDraft: draft } };
